{
  "id": 22,
  "knowledge": "Suspicious Transaction Pattern",
  "description": "Identifies transactions with characteristics suggesting potential illegal activity",
  "definition": "A transaction with TAS > 75, payment in privacy-focused cryptocurrencies (Crypto_B), escrow disabled or minimized (escrowused = 'No' or escrowhrs < 24), and unusual routing complexity (routecomplexity = 'Complex'). These transactions often represent high-risk activities requiring further investigation."
}

{
  "id": 34,
  "knowledge": "Transaction Velocity Metric (TVM)",
  "description": "Measures the rapidity and volume of transactions from a single source",
  "definition": "TVM = \\frac{COUNT(txregistry)}{(MAX(eventstamp) - MIN(eventstamp))} \\times \\frac{payamtusd}{500} \\times (1 + (paymethod\\_weight \\times 0.1)), \\text{where paymethod\\_weight assigns Crypto\\_A=1, Crypto\\_B=3, Crypto\\_C=2, Token=2 based on the payment method classifications defined in cybermarket|transactions|paymethod, and higher values indicate potentially suspicious transaction velocity.}"
}

{
  "id": 16,
  "knowledge": "Transaction Chain Risk (TCR)",
  "description": "Evaluates the risk level of a transaction chain",
  "definition": "TCR = (txchainlen \\times 10) + (linkedtxcount \\times 5) + (fraudprob \\times 100) - (profilecomplete \\times 0.5) - (idverifyscore \\times 0.5), \\text{where higher scores indicate higher risk transaction chains.}"
}

{
  "id": 39,
  "knowledge": "Money Flow Complexity (MFC)",
  "description": "Quantifies the complexity of money flows in transaction chains",
  "definition": "MFC = (txchainlen \\times 5) + (linkedtxcount \\times 3) + (moneyrisk_numeric \\times 15) + (TCR \\times 0.2) - (profilecomplete \\times 10), \\text{where moneyrisk_numeric maps Low=1, Medium=2, High=3, Unknown=2 according to the money laundering risk classification, and higher scores indicate more complex money flows.}"
}

{
  "id": 33,
  "knowledge": "Communication Pattern Risk (CPR)",
  "description": "Evaluates how suspicious a communication pattern is based on multiple factors",
  "definition": "CPR = (langpattern_numeric \\times 15) + (CSR \\times 0.2) + (msgtally \\times 0.5) - (1 - vpnflag_numeric) \\times 20, \\text{where langpattern_numeric maps Consistent=1, Variable=2, Suspicious=3 as explained in the language pattern classification, and higher scores represent more suspicious communication behavior.}"
}

{
  "id": 14,
  "knowledge": "Wallet Risk Index (WRI)",
  "description": "Assesses the risk level of cryptocurrency wallets",
  "definition": "WRI = (fraudprob \\times 100) + (wallrisksc \\times 0.5) - \\frac{wallage}{30} + (wallturnrt \\times 10) + \\frac{txvel}{10}, \\text{where higher scores indicate potentially suspicious wallet activity.}"
}

{
  "id": 38,
  "knowledge": "Cross-Platform Risk Amplification (CPRA)",
  "description": "Measures how risk increases when an entity operates across multiple platforms",
  "definition": "CPRA = (keymatchcount \\times 3) + (COUNT(DISTINCT mktref) \\times 10) + (WRI \\times 0.2) + (\\frac{mktspan}{365} \\times 5) - (\\frac{compliancescore}{20}), \\text{where WRI is defined by the Wallet Risk Index, platformcount is the count of distinct markets an entity operates on, and higher values indicate greater cross-platform risk.}"
}

{
  "id": 32,
  "knowledge": "Product Risk Exposure (PRE)",
  "description": "Quantifies the regulatory exposure risk associated with product listings",
  "definition": "PRE = prodtheme_weight + (escrowused_numeric \\times 10) - \\frac{escrowhrs}{24} + \\frac{payamtusd}{500}, \\text{where prodtheme_weight assigns Digital=10, Data=20, Service=30, Physical=50 based on the product theme classification, and escrowused_numeric is 0 if escrow is used and 1 if not.}"
}

{
  "id": 31,
  "knowledge": "Vendor Network Centrality (VNC)",
  "description": "Measures a vendor's connectedness within the market ecosystem",
  "definition": "VNC = (COUNT(DISTINCT mktref) \\times 5) + \\frac{vendtxcount}{50} + (VTI \\times 0.1) - (1 - sizecluster_numeric) \\times 10, \\text{where sizecluster_numeric maps Small=1, Medium=2, Large=3, Mega=4 as described in the market size classification, and higher scores indicate more central market positioning.}"
}

{
  "id": 30,
  "knowledge": "Market Vulnerability Index (MVI)",
  "description": "Evaluates a market's susceptibility to disruption or shutdown",
  "definition": "MVI = (100 - MSI) + (COUNT(CASE WHEN alertsev IS NOT NULL THEN 1 END) / 10) \\times (alertsev_numeric \\times 2) - (vendcount \\times 0.05) + (COUNT(CASE WHEN lawinterest = 'High' THEN 1 END) / 5), \\text{where alertsev_numeric maps Low=1, Medium=2, High=3, Critical=4 as defined in the alert severity system, and higher scores indicate greater vulnerability to disruption.}"
}

{
  "id": 10,
  "knowledge": "Market Risk Score (MRS)",
  "description": "Calculates overall risk level of a market based on multiple factors",
  "definition": "MRS = \\frac{dlyflow}{1000} + (esccomprate \\times 0.2) + (interscore \\times 0.3) + (vendcount \\times 0.1) - \\frac{mktspan}{100}, \\text{where higher scores indicate greater risk exposure requiring enhanced monitoring.}"
}

{
  "id": 11,
  "knowledge": "Vendor Trust Index (VTI)",
  "description": "Measures vendor reliability based on transaction history",
  "definition": "VTI = \\frac{vendsucccount}{vendtxcount} \\times 100 - \\frac{venddisputecount}{vendtxcount} \\times 50 + (vendrate \\times 5), \\text{where higher scores indicate more trustworthy vendors.}"
}

{
  "id": 13,
  "knowledge": "Communication Security Risk (CSR)",
  "description": "Evaluates the security risk of a communication channel",
  "definition": "CSR = (iptally \\times 5) + (tornodecount \\times 2) + (vpnflag\\_numeric \\times 30) + \\frac{brwsrunique}{10} + (susppatscore \\times 3) + (riskindiccount \\times 4), \\text{where vpnflag\\_numeric maps Yes=1, Suspected=0.5, No=0, and higher scores indicate greater security concerns.}"
}

{
  "id": 15,
  "knowledge": "Market Stability Index (MSI)",
  "description": "Measures the operational stability of a market",
  "definition": "MSI = \\frac{mktspan}{365} \\times \\frac{esccomprate}{100} \\times \\left(1 - \\frac{\\sum venddisputecount}{\\sum vendtxcount} \\right) \\times 100, \\text{where higher scores indicate more stable markets less likely to disappear suddenly.}"
}

{
  "id": 17,
  "knowledge": "Security Posture Score (SPS)",
  "description": "Evaluates the overall security posture of an entity",
  "definition": "SPS = (100 - (vulntally \\times 5)) + (securitymeasurecount \\times 2) + (sessionsecurityscore \\times 0.5) + (privprotscore \\times 0.3) - (fpprob \\times 100), \\text{where higher scores indicate stronger security postures.}"
}

{
  "id": 18,
  "knowledge": "Investigation Priority Score (IPS)",
  "description": "Determines how urgently an investigation should be handled",
  "definition": "IPS = (lawinterest\\_numeric \\times 30) + (regrisklvl\\_numeric \\times 20) + (fraudprob \\times 100) - (compliancescore \\times 0.5) + (notescount \\times 2), \\text{where lawinterest\\_numeric and regrisklvl\\_numeric map Low=1, Medium=2, High=3, Unknown=2, and higher scores indicate higher priority.}"
}

{
  "id": 19,
  "knowledge": "Anonymity Protection Level (APL)",
  "description": "Measures how well a user's identity is protected",
  "definition": "APL = (vpnflag\\_numeric \\times 30) + (tornodecount \\times 2) + (encryptmethod\\_numeric \\times 15) + (connpatscore \\times 0.2) + \\frac{brwsrunique}{20}, \\text{where vpnflag\\_numeric maps Yes=1, Suspected=0.5, No=0, encryptmethod\\_numeric maps Standard=1, Enhanced=2, Custom=3, else=0 and higher scores indicate stronger anonymity protections.}"
}

{
  "id": 35,
  "knowledge": "Market Diversification Score (MDS)",
  "description": "Evaluates the diversity of products and vendors within a market",
  "definition": "MDS = \\frac{COUNT(DISTINCT prodsubcat)}{5} + \\frac{vendcount}{50} + \\frac{COUNT(txregistry)}{vendcount} \\times 0.5 - \\frac{mktclass\\_weight}{10}, \\text{where mktclass\\_weight assigns Forum=1, Service=2, Marketplace=4, Exchange=3 as per the market classification system defined in cybermarket|markets|mktclass, and higher scores represent greater market diversification.}"
}

{
  "id": 36,
  "knowledge": "Operational Security Index (OSI)",
  "description": "Quantifies an entity's operational security practices",
  "definition": "OSI = (APL \\times 0.5) + (SPS \\times 0.2) + (tornodecount \\times 2) + (CASE WHEN encryptmethod = 'Standard' THEN 1 WHEN encryptmethod = 'Enhanced' THEN 2 WHEN encryptmethod = 'Custom' THEN 3 ELSE 0 END \\times 5) - (iptally \\times 0.5), \\text{where APL and SPS are defined by the Anonymity Protection Level and Security Posture Score respectively, and higher scores indicate stronger operational security.}"
}

{
  "id": 37,
  "knowledge": "Vendor Relationship Strength (VRS)",
  "description": "Measures the strength of relationships between a vendor and their customers",
  "definition": "VRS = (vendrate \\times 10) + \\frac{vendsucccount}{vendtxcount} \\times 50 + (vendchecklvl_numeric \\times 15) - \\frac{venddisputecount}{vendtxcount} \\times 100, \\text{where vendchecklvl_numeric maps Basic=1, Advanced=2, Premium=3, else=0 according to the vendor verification system, and higher scores represent stronger vendor-customer relationships.}"
}

